import React, { useState } from 'react'
import { Box, Text, useInput } from 'ink'
import { COMMAND_SUGGESTIONS } from '../commands.js'

function getSuggestion(value: string): string {
  if (!value.startsWith('/')) return ''
  const match = COMMAND_SUGGESTIONS.find((s) => s.startsWith(value) && s !== value)
  return match ? match.slice(value.length) : ''
}

export function InputBox({ onSubmit, isLoading }: { onSubmit: (text: string) => void; isLoading: boolean }) {
  const [value, setValue] = useState('')

  const suggestion = getSuggestion(value)

  useInput((input, key) => {
    if (isLoading) return
    if (key.return) {
      onSubmit(value)
      setValue('')
      return
    }
    if (key.tab && suggestion) {
      setValue(value + suggestion)
      return
    }
    if (key.backspace || key.delete) {
      setValue((v) => v.slice(0, -1))
      return
    }
    if (input && !key.ctrl && !key.meta) {
      setValue((v) => v + input)
    }
  })

  return (
    <Box>
      <Text color={isLoading ? 'gray' : 'green'}>{`> `}</Text>
      {isLoading ? (
        <Text>...</Text>
      ) : (
        <>
          <Text>{value}</Text>
          {suggestion && <Text dimColor>{suggestion}</Text>}
          <Text color="gray">█</Text>
        </>
      )}
    </Box>
  )
}

