import OpenAI from 'openai'
import { allTools, toolMap } from './tools/index.js'
import type { ChatCompletionMessageParam, ChatCompletionTool } from 'openai/resources/chat/completions'
import type { Model } from './commands.js'

const SYSTEM_PROMPT = 'You are DeepSeek Code, an AI coding assistant with access to the filesystem and shell.'

const openaiTools: ChatCompletionTool[] = allTools.map((t) => ({
  type: 'function' as const,
  function: { name: t.name, description: t.description, parameters: t.parameters as Record<string, unknown> },
}))

export interface AgentCallbacks {
  onToken(text: string): void
  onToolCall(name: string, args: object): void
  onToolResult(name: string, result: string): void
  onDone(): void
}

export class Agent {
  private client: OpenAI
  private messages: ChatCompletionMessageParam[] = [{ role: 'system', content: SYSTEM_PROMPT }]
  public tokenCount = 0
  public model: Model = 'deepseek-chat'

  constructor() {
    this.client = new OpenAI({
      apiKey: process.env.DEEPSEEK_API_KEY,
      baseURL: 'https://api.deepseek.com',
    })
  }

  setModel(m: Model) { this.model = m }
  clearHistory() { this.messages = [{ role: 'system', content: SYSTEM_PROMPT }] }

  async run(userMessage: string, cb: AgentCallbacks) {
    this.messages.push({ role: 'user', content: userMessage })
    await this.loop(cb)
  }

  private async loop(cb: AgentCallbacks) {
    while (true) {
      const stream = await this.client.chat.completions.create({
        model: this.model,
        messages: this.messages,
        tools: openaiTools,
        stream: true,
      })

      let assistantText = ''
      const toolCalls: Map<number, { id: string; name: string; args: string }> = new Map()

      for await (const chunk of stream) {
        const delta = chunk.choices[0]?.delta
        if (!delta) continue

        if (delta.content) {
          assistantText += delta.content
          cb.onToken(delta.content)
        }

        if (delta.tool_calls) {
          for (const tc of delta.tool_calls) {
            const idx = tc.index
            if (!toolCalls.has(idx)) {
              toolCalls.set(idx, { id: tc.id || '', name: tc.function?.name || '', args: '' })
            }
            const entry = toolCalls.get(idx)!
            if (tc.id) entry.id = tc.id
            if (tc.function?.name) entry.name = tc.function.name
            if (tc.function?.arguments) entry.args += tc.function.arguments
          }
        }

        if (chunk.usage) {
          this.tokenCount += chunk.usage.total_tokens
        }
      }

      if (toolCalls.size === 0) {
        this.messages.push({ role: 'assistant', content: assistantText })
        cb.onDone()
        return
      }

      // Build assistant message with tool_calls
      const tcArray = [...toolCalls.values()].map((tc) => ({
        id: tc.id,
        type: 'function' as const,
        function: { name: tc.name, arguments: tc.args },
      }))
      this.messages.push({ role: 'assistant', content: assistantText || null, tool_calls: tcArray })

      // Execute each tool
      for (const tc of tcArray) {
        let parsedArgs: Record<string, unknown> = {}
        try { parsedArgs = JSON.parse(tc.function.arguments) } catch {}
        cb.onToolCall(tc.function.name, parsedArgs)

        const tool = toolMap.get(tc.function.name)
        let result: string
        if (tool) {
          try { result = await tool.execute(parsedArgs) } catch (e: unknown) {
            result = `Error: ${(e as Error).message}`
          }
        } else {
          result = `Unknown tool: ${tc.function.name}`
        }

        cb.onToolResult(tc.function.name, result)
        this.messages.push({ role: 'tool', tool_call_id: tc.id, content: result })
      }
      // Loop continues to get next response
    }
  }
}

import React, { useState, useCallback } from 'react'
import { Box, Text, useInput, useApp } from 'ink'
import { Agent } from '../agent.js'
import { MessageList } from './MessageList.js'
import { ToolUseDisplay } from './ToolUseDisplay.js'
import { InputBox } from './InputBox.js'
import { StatusBar } from './StatusBar.js'
import { parseCommand, HELP_TEXT } from '../commands.js'

export interface Message {
  role: 'user' | 'assistant' | 'tool'
  content: string
}

export interface ToolStatus {
  name: string
  args: string
  done: boolean
  result?: string
}

export function App() {
  const { exit } = useApp()
  const [messages, setMessages] = useState<Message[]>([])
  const [streamText, setStreamText] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [toolStatus, setToolStatus] = useState<ToolStatus | null>(null)
  const [tokenCount, setTokenCount] = useState(0)
  const [agent] = useState(() => new Agent())

  useInput((_, key) => {
    if (key.ctrl && key.return) return
    if (key.escape) { exit(); process.exit(0) }
  })

  const handleSubmit = useCallback(async (text: string) => {
    if (!text.trim() || isLoading) return

    const cmd = parseCommand(text)
    if (cmd) {
      switch (cmd.type) {
        case 'quit': exit(); process.exit(0)
        case 'clear':
          agent.clearHistory()
          setMessages([])
          return
        case 'help':
          setMessages((m) => [...m, { role: 'assistant', content: HELP_TEXT }])
          return
        case 'model':
          agent.setModel(cmd.model)
          setMessages((m) => [...m, { role: 'assistant', content: `Model switched to ${cmd.model}` }])
          return
        case 'unknown':
          setMessages((m) => [...m, { role: 'assistant', content: cmd.input }])
          return
      }
    }

    setMessages((m) => [...m, { role: 'user', content: text }])
    setIsLoading(true)
    setStreamText('')

    await agent.run(text, {
      onToken(token) {
        setStreamText((s) => s + token)
      },
      onToolCall(name, args) {
        setToolStatus({ name, args: JSON.stringify(args).slice(0, 100), done: false })
      },
      onToolResult(name, result) {
        setToolStatus({ name, args: '', done: true, result: result.slice(0, 200) })
      },
      onDone() {
        setToolStatus(null)
        setStreamText((s) => {
          if (s) setMessages((m) => [...m, { role: 'assistant', content: s }])
          return ''
        })
        setIsLoading(false)
        setTokenCount(agent.tokenCount)
      },
    })
  }, [agent, isLoading, exit])

  return (
    <Box flexDirection="column" width="100%">
      <MessageList messages={messages} streamText={streamText} />
      {toolStatus && <ToolUseDisplay tool={toolStatus} />}
      <InputBox onSubmit={handleSubmit} isLoading={isLoading} />
      <StatusBar tokenCount={tokenCount} />
    </Box>
  )
}

#!/usr/bin/env bun
import React, { useState, useEffect } from 'react'
import { render, Box, Text } from 'ink'
import { App } from './ui/App.js'
import { ApiKeySetup, loadSavedConfig, type ThemeName } from './ui/ApiKeySetup.js'
import { DeepSeekMascot } from './ui/Mascot.js'

function Root() {
  const [ready, setReady] = useState(false)
  const [checked, setChecked] = useState(false)
  const [theme, setTheme] = useState<ThemeName>('dark')

  useEffect(() => {
    loadSavedConfig().then(({ apiKey, theme: savedTheme }) => {
      setTheme(savedTheme)
      if (process.env.DEEPSEEK_API_KEY) {
        setReady(true)
      } else if (apiKey) {
        process.env.DEEPSEEK_API_KEY = apiKey
        setReady(true)
      }
      setChecked(true)
    })
  }, [])

  if (!checked) return null

  if (!ready) {
    return (
      <Box flexDirection="column" paddingX={2} paddingY={1}>
        <ApiKeySetup onDone={(t) => { setTheme(t); setReady(true) }} />
      </Box>
    )
  }

  return (
    <Box flexDirection="column" borderStyle="round" borderColor="cyan">
      <Box flexDirection="row" paddingX={1} gap={2} alignItems="center">
        <DeepSeekMascot />
        <Box flexDirection="column" justifyContent="center">
          <Text bold color="cyan">DeepSeek Code <Text dimColor>v0.1.0</Text></Text>
          <Text dimColor>deepseek-chat · {process.cwd()}</Text>
          <Text dimColor>Type your message and press Enter. /quit or Esc to exit.</Text>
        </Box>
      </Box>
      <App />
    </Box>
  )
}

const { waitUntilExit } = render(<Root />)
waitUntilExit().then(() => process.exit(0))

