import { join } from 'path'
import { readFile } from 'fs/promises'

const STEERING_DIR = join(process.cwd(), '.deepseek', 'steering')

export async function loadSteering(): Promise<string> {
  const glob = new Bun.Glob('*.md')
  const parts: string[] = []

  try {
